/**
 * Compiles the Solidity contracts with solc-js and writes typed TypeScript artifacts:
 *
 *   contracts/LightningHtlc.sol      -> src/evm/lightning-htlc.generated.ts
 *   contracts/test/MockUSDC.sol      -> test/support/mock-usdc.generated.ts
 *
 * The generated files are committed, so the solver never compiles at runtime.
 * Run with `pnpm compile:contract` after editing a contract.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const solc = require("solc") as { compile(input: string): string; version(): string };

type Output = {
  errors?: Array<{ severity: "error" | "warning" | "info"; formattedMessage: string }>;
  contracts: Record<
    string,
    Record<string, { abi: unknown[]; evm: { bytecode: { object: string }; deployedBytecode: { object: string } } }>
  >;
};

const sources = {
  "LightningHtlc.sol": { content: readFileSync("contracts/LightningHtlc.sol", "utf8") },
  "test/MockUSDC.sol": { content: readFileSync("contracts/test/MockUSDC.sol", "utf8") },
};

const input = {
  language: "Solidity",
  sources,
  settings: {
    optimizer: { enabled: true, runs: 1000 },
    evmVersion: "cancun",
    outputSelection: { "*": { "*": ["abi", "evm.bytecode.object", "evm.deployedBytecode.object"] } },
  },
};

const output = JSON.parse(solc.compile(JSON.stringify(input))) as Output;
const errors = (output.errors ?? []).filter((e) => e.severity === "error");
for (const e of output.errors ?? []) console.error(e.formattedMessage);
if (errors.length) process.exit(1);

const emit = (file: string, contract: string, path: string, constPrefix: string) => {
  const artifact = output.contracts[file]?.[contract];
  if (!artifact) throw new Error(`missing artifact for ${file}:${contract}`);
  const body = `// Generated by scripts/compile-contract.ts from contracts/${file} (solc ${solc.version()}). Do not edit.

export const ${constPrefix}Abi = ${JSON.stringify(artifact.abi, null, 2)} as const;

export const ${constPrefix}Bytecode = "0x${artifact.evm.bytecode.object}" as const;

export const ${constPrefix}DeployedBytecode = "0x${artifact.evm.deployedBytecode.object}" as const;
`;
  writeFileSync(path, body);
  console.log(`wrote ${path} (${artifact.evm.deployedBytecode.object.length / 2} bytes deployed)`);
};

emit("LightningHtlc.sol", "LightningHtlc", "src/evm/lightning-htlc.generated.ts", "lightningHtlc");
emit("test/MockUSDC.sol", "MockUSDC", "test/support/mock-usdc.generated.ts", "mockUsdc");
